mapper.select:
with recursive folder_tree as ( -- 递归获取每个文件夹的所有子文件夹（包括自己） -- 根节点保留全部（含停用），递归时排除停用的子文件夹，使停用子文件夹不计入数量 select id as root_id, id as sub_id from px_wallpaper_folder where del_flag = 0 union all select ft.root_id, f.id as sub_id from px_wallpaper_folder f inner join folder_tree ft on f.parent_id = ft.sub_id where f.del_flag = 0 and f.enabled = 1 ) select f.id, f.name, coalesce(nullif(f.cover, ''), (select coalesce(nullif(w.thumbnail, ''), w.url) from folder_tree ft2 inner join px_wallpaper w on ft2.sub_id = w.folder and w.del_flag = 0 where ft2.root_id = f.id order by isnull(w.`order`) || w.`order` = '', w.`order`, w.update_time desc limit 1)) as cover, f.parent_id, f.`order`, f.del_flag, f.enabled, f.version, f.create_by, f.create_time, f.update_by, f.update_time, f.remark, coalesce(wps.cnt, 0) as wallpaper_count from px_wallpaper_folder f left join ( select root_id, count(*) as cnt from folder_tree ft inner join px_wallpaper w on ft.sub_id = w.folder and w.del_flag = 0 group by root_id ) wps on f.id = wps.root_id
f.del_flag = 0
and f.name like concat('%', #{name}, '%')
and f.parent_id = #{parentId}
and f.enabled = #{enabled}
and f.version = #{version}
ORDER BY isnull(f.`order`) || f.`order` = '', f.`order`, f.update_time DESC

select f.id, f.name, coalesce(nullif(f.cover, ''), wc.first_cover) as cover, f.parent_id, f.`order`, f.del_flag, f.enabled, f.version, f.create_by, f.create_time, f.update_by, f.update_time, f.remark, coalesce(wc.cnt, 0) as wallpaper_count from px_wallpaper_folder f left join ( select w.folder as fid, count(*) as cnt, (select coalesce(nullif(w2.thumbnail, ''), w2.url) from px_wallpaper w2 where w2.folder = w.folder and w2.del_flag = 0 order by isnull(w2.`order`) || w2.`order` = '', w2.`order`, w2.update_time desc limit 1) as first_cover from px_wallpaper w where w.del_flag = 0 group by w.folder ) wc on wc.fid = f.id
f.del_flag = 0
and f.name like concat('%', #{name}, '%')
and f.parent_id = #{parentId}
and f.enabled = #{enabled}
and f.version = #{version}
ORDER BY isnull(f.`order`) || f.`order` = '', f.`order`, f.update_time DESC

mapper.update:
update px_wallpaper_folder
name = #{name}, cover = #{cover}, parent_id = #{parentId}, `order` = #{order}, del_flag = #{delFlag}, enabled = #{enabled}, version = #{version}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where id = #{id}

mapper.delete:
update px_wallpaper_folder
set del_flag = 1
where id = #{id}
